      align-items: center;
      justify-content: center;
      cursor: pointer;
      border: none;
      color: var(--gray-600);
      font-size: 20px;
      transition: all var(--transition);
      flex-shrink: 0;
    }
    .modal-close:hover { background: var(--gray-200); color: var(--gray-900); }
    .modal-body { padding: 28px; }
    .modal-freq-tabs {
      display: flex;
      background: var(--gray-100);
      border-radius: 8px;
      padding: 4px;
      gap: 4px;
      margin-bottom: 24px;
    }
    .modal-freq-tab {
      flex: 1;
      padding: 10px;
      text-align: center;
      font-size: 14px;
      font-weight: 600;
      border-radius: 6px;
      cursor: pointer;
      border: none;
      background: none;
      font-family: inherit;
      color: var(--gray-600);
      transition: all var(--transition);
    }
    .modal-freq-tab.active {
      background: var(--white);
      color: var(--navy);
      box-shadow: var(--shadow-sm);
    }
    .modal-section-label {
      font-size: 13px;
      font-weight: 600;
      color: var(--gray-600);
      text-transform: uppercase;
      letter-spacing: 0.06em;
      margin-bottom: 12px;
    }
    .modal-amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-bottom: 12px;
    }
    .modal-amount-btn {
      padding: 16px 8px;
      border: 2px solid var(--gray-200);
      border-radius: 8px;
      background: var(--white);
      cursor: pointer;
      text-align: center;
      font-family: inherit;
      transition: all var(--transition);
    }
    .modal-amount-btn:hover { border-color: var(--red); }
    .modal-amount-btn.selected { border-color: var(--red); background: rgba(196,30,58,0.06); }
    .modal-amount-btn .m-amount {
      font-size: 22px;
      font-weight: 800;
      color: var(--navy);
      display: block;
      line-height: 1;
      margin-bottom: 5px;
    }
    .modal-amount-btn.selected .m-amount { color: var(--red); }
    .modal-amount-btn .m-impact {
      font-size: 11px;
      color: var(--gray-500);
      line-height: 1.35;
    }
    .modal-custom-wrap {
      display: flex;
      border: 2px solid var(--gray-200);
      border-radius: 8px;
      overflow: hidden;
      margin-bottom: 24px;
    }
    .modal-custom-wrap:focus-within { border-color: var(--navy); }
    .modal-custom-prefix {
      padding: 14px 16px;
      background: var(--gray-100);
      font-size: 18px;
      font-weight: 700;
      color: var(--gray-600);
    }
    .modal-custom-input {
      flex: 1;
      border: none;
      padding: 14px 16px;
      font-size: 18px;
      font-weight: 700;
      font-family: inherit;
      color: var(--navy);
      outline: none;
    }
    .modal-custom-input::placeholder { color: var(--gray-400); font-weight: 400; }
    .modal-impact-note {
      padding: 14px 18px;
      background: rgba(27,58,92,0.06);
      border-radius: 8px;
      border-left: 3px solid var(--navy);
      font-size: 14px;
      color: var(--gray-700);
      margin-bottom: 24px;
      min-height: 50px;
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .modal-impact-note i { color: var(--navy); font-size: 18px; flex-shrink: 0; }
    .modal-donate-btn {
      width: 100%;
      padding: 18px;
      background: var(--red);
      color: var(--white);
      border: none;
      border-radius: 8px;
      font-size: 17px;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      transition: all var(--transition);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      margin-bottom: 12px;
    }
    .modal-donate-btn:hover { background: var(--red-dark); }
    .modal-secure {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      font-size: 12px;
      color: var(--gray-500);
      margin-bottom: 8px;
    }
    .modal-secure i { color: #16a34a; font-size: 14px; }
    .modal-tax-note {
      text-align: center;
      font-size: 12px;
      color: var(--gray-400);
