  <script>
    // ===== MOBILE MENU =====
    const hamburgerBtn = document.getElementById('hamburgerBtn');
    const mobileNav = document.getElementById('mobileNav');

    hamburgerBtn.addEventListener('click', () => {
      const isOpen = mobileNav.classList.toggle('open');
      hamburgerBtn.classList.toggle('open', isOpen);
      hamburgerBtn.setAttribute('aria-expanded', isOpen);
      document.body.style.overflow = isOpen ? 'hidden' : '';
    });

    function closeMenu() {
      mobileNav.classList.remove('open');
      hamburgerBtn.classList.remove('open');
      hamburgerBtn.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    }

    // Close on outside click
    mobileNav.addEventListener('click', (e) => {
      if (e.target === mobileNav) closeMenu();
    });

    // ===== ACCORDION =====
    document.querySelectorAll('.accordion-trigger').forEach(trigger => {
      trigger.addEventListener('click', () => {
        const item = trigger.closest('.accordion-item');
        const isOpen = item.classList.contains('open');

        // Close all
        document.querySelectorAll('.accordion-item').forEach(el => {
          el.classList.remove('open');
          el.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
        });

        // Open clicked if it was closed
        if (!isOpen) {
          item.classList.add('open');
          trigger.setAttribute('aria-expanded', 'true');
        }
      });
    });

    // ===== NEWS CAROUSEL =====
    const carousel = document.getElementById('newsCarousel');
    const prevBtn = document.getElementById('newsPrev');
    const nextBtn = document.getElementById('newsNext');
    const dots = document.querySelectorAll('.news-dot');
    let currentSlide = 0;

    function getCardsPerView() {
      return window.innerWidth <= 768 ? 1 : 3;
    }

    function getTotalSlides() {
      const cards = carousel.querySelectorAll('.news-card');
      return Math.ceil(cards.length / getCardsPerView()) - 1 + (cards.length % getCardsPerView() === 0 ? 1 : 0);
    }

    function updateCarousel() {
      const cards = carousel.querySelectorAll('.news-card');
      const perView = getCardsPerView();
      const cardWidth = carousel.parentElement.offsetWidth;
      const gap = 24;
      const slideWidth = perView === 1 ? cardWidth : (cardWidth / perView - gap * (perView - 1) / perView);
      const offset = currentSlide * (slideWidth + gap) * perView;

      carousel.style.transform = `translateX(-${offset}px)`;
      prevBtn.disabled = currentSlide === 0;

      const maxSlide = Math.ceil(cards.length / perView) - 1;
      nextBtn.disabled = currentSlide >= maxSlide;

      dots.forEach((d, i) => d.classList.toggle('active', i === currentSlide));
    }

    prevBtn.addEventListener('click', () => {
      if (currentSlide > 0) { currentSlide--; updateCarousel(); }
    });

    nextBtn.addEventListener('click', () => {
      const cards = carousel.querySelectorAll('.news-card');
      const maxSlide = Math.ceil(cards.length / getCardsPerView()) - 1;
      if (currentSlide < maxSlide) { currentSlide++; updateCarousel(); }
    });

    dots.forEach((dot, i) => {
      dot.addEventListener('click', () => { currentSlide = i; updateCarousel(); });
    });

    window.addEventListener('resize', () => { currentSlide = 0; updateCarousel(); });

    // ===== STATS COUNTER ANIMATION =====
    function animateCounter(el) {
      const target = parseFloat(el.dataset.target);
      const prefix = el.dataset.prefix || '';
      const suffix = el.dataset.suffix || '';
      const format = el.dataset.format;
      const duration = 2000;
      const start = performance.now();

      function update(now) {
        const elapsed = now - start;
        const progress = Math.min(elapsed / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const value = Math.floor(eased * target);

        let display = value;
        if (format === 'comma') {
          display = value.toLocaleString();
        }

        el.textContent = prefix + display + suffix;

        if (progress < 1) requestAnimationFrame(update);
        else el.textContent = prefix + (format === 'comma' ? target.toLocaleString() : target) + suffix;
      }
      requestAnimationFrame(update);
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting && !entry.target.dataset.animated) {
          entry.target.dataset.animated = 'true';
          animateCounter(entry.target);
        }
      });
    }, { threshold: 0.3 });

    document.querySelectorAll('.stat-number[data-target]').forEach(el => observer.observe(el));

    // ===== DONATION MODAL =====
    const modal = document.getElementById('donateModal');
    let selectedAmount = 50;

    function openModal(e) {
      if (e) e.preventDefault();
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
      updateModalDonateBtn();
    }

    function closeModal() {
      modal.classList.remove('open');
      document.body.style.overflow = '';
    }

    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('open')) closeModal();
    });

    function setFrequency(btn, freq) {
      document.querySelectorAll('.modal-freq-tab').forEach(t => t.classList.remove('active'));
      btn.classList.add('active');
    }

    function selectModalAmount(btn, amount) {
      document.querySelectorAll('.modal-amount-btn').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      if (amount !== 'custom') {
        selectedAmount = amount;
        document.getElementById('modalCustomAmount').value = '';
        updateImpactNote(amount);
        updateModalDonateBtn(amount);
      } else {
        document.getElementById('modalCustomAmount').focus();
      }
    }

    const impactMessages = {
      25: 'Your $25 donation provides 5 emergency blankets for displaced families.',
      50: 'Your $50 donation provides a family with food and water for one week.',
      100: 'Your $100 donation funds emergency shelter materials for a household.',
      250: 'Your $250 donation equips a volunteer with disaster response training.',
      500: 'Your $500 donation equips a full emergency response team.',
    };

    function updateImpactNote(amount) {
      const val = parseInt(amount);
      const note = document.getElementById('modalImpactNote');
      const span = note.querySelector('span');
      if (!val || val < 1) {
        span.textContent = 'Every dollar you give goes directly to those who need it most.';
        return;
      }
      selectedAmount = val;
      updateModalDonateBtn(val);
      if (impactMessages[val]) {
        span.textContent = impactMessages[val];
      } else if (val > 0) {
        span.textContent = `Your $${val} donation helps us reach communities in crisis worldwide.`;
      }
    }

    function updateModalDonateBtn(amount) {
      const amt = amount || selectedAmount;
      const label = document.getElementById('modalDonateLabel');
      if (label) label.textContent = `Donate $${amt}`;
    }

    function submitDonation() {
      const customVal = document.getElementById('modalCustomAmount').value;
      const finalAmount = customVal ? parseInt(customVal) : selectedAmount;
      alert(`Thank you! You are donating $${finalAmount} to Global Aid Alliance.\n\nIn a live site, this would proceed to a secure payment form.`);
      closeModal();
    }

    // ===== SECTION AMOUNT SELECTOR =====
    function selectAmount(btn, amount) {
      document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
    }

    // Init
    updateCarousel();
  </script>
